import (
	"fmt"
)

resp, err := client.TaxSettings().GetTaxSettings(ctx, nil, nil)
if err != nil {
	log.Fatal(err)
}
settings := resp.Map().(map[string]any)["tax_settings"].(map[string]any)
fmt.Println(settings["default_country"], settings["default_tax_code"], settings["tax_message"])

